# =============================================================================
# verify_fast_pre.R -- is bagoft_fast_pre() the SAME test as BAGofT 1.0.0 on the niche
# datasets (n = 200, ten covariates, so parRF's dcPre() pre-selection runs in every split)?
#
# The 20 datasets: null_n200 reps 1-6; inter and quad at C = .3, .5, .8, reps 1-2; inter_C0.8
# and quad_C0.8 rep 3. Each dataset is generated by niche_addon.R's own code (parsed out of it)
# with seed 123000 + id * 100000 + rep, and both functions get the RNG seeded with
# seed + 500000000, exactly as niche_addon.R's BAGofT mode seeds the package.
#
#   stage A  nsplits = 10, nsim = 5: every output -- three p-values, three statistics and the
#            15 simulated statistics -- must be identical() (a quick check of every branch)
#   stage B  nsplits = 100, nsim = 100 (the arm's settings): p.value, p.value2, p.value3 and
#            the statistics compared, plus the simulated statistics; the times of both
#
# Run:  Rscript verify_fast_pre.R A
#       Rscript verify_fast_pre.R B <part> <nparts>     (dataset i goes to part (i - 1) %% nparts + 1)
# Writes one CSV per dataset to verify_fast_pre/<stage>_<scen>_r<rep>.csv (resumable), and
# Rscript verify_fast_pre.R summary  writes verify_fast_pre.csv and prints the verdict.
# =============================================================================
HERE <- "/path/to/project/paper_deepgof/theory/addon_arms"
args <- commandArgs(TRUE)
STAGE <- if (length(args)) args[1] else "A"
PART  <- if (length(args) >= 2) as.integer(args[2]) else 1L
NPART <- if (length(args) >= 3) as.integer(args[3]) else 1L
VD <- file.path(HERE, "verify_fast_pre"); dir.create(VD, showWarnings = FALSE)

if (STAGE == "summary") {
  fs <- list.files(VD, pattern = "^[AB]_.*\\.csv$", full.names = TRUE)
  d  <- do.call(rbind, lapply(fs, utils::read.csv))
  d  <- d[order(d$stage, d$scen, d$rep), ]
  utils::write.csv(d, file.path(HERE, "verify_fast_pre.csv"), row.names = FALSE)
  for (st in unique(d$stage)) {
    x <- d[d$stage == st, ]
    cat(sprintf("stage %s: %d datasets | all outputs identical: %d | p.value identical: %d | p.value3 identical: %d | max |dp| %.3g\n",
                st, nrow(x), sum(x$all_identical), sum(x$p_identical), sum(x$p3_identical),
                max(abs(x$p_pkg - x$p_fast))))
    cat(sprintf("  package time %.1f s mean, fast %.1f s mean, ratio %.1f\n",
                mean(x$t_pkg), mean(x$t_fast), mean(x$t_pkg) / mean(x$t_fast)))
  }
  quit(save = "no")
}

## the niche generator, parsed out of niche_addon.R (not re-typed)
ex <- parse(file.path(HERE, "niche_addon.R"))
keep <- vapply(ex, function(e) {
  s <- paste(deparse(e), collapse = " ")
  grepl("^(CH|SEEDB|NNULL|NALT|SC) <-", s) || grepl("^SC\\$", s) || grepl("^niche_defs <-", s)
}, TRUE)
for (e in ex[keep]) eval(e, globalenv())
eval(niche_defs)

source(file.path(HERE, "bagoft_fast_pre.R"))
suppressPackageStartupMessages({ library(BAGofT); library(randomForest); library(dcov) })

DS <- rbind(data.frame(scen = "null_n200", rep = 1:6),
            data.frame(scen = rep(c("inter_C0.3_n200", "inter_C0.5_n200", "inter_C0.8_n200",
                                    "quad_C0.3_n200", "quad_C0.5_n200", "quad_C0.8_n200"), each = 2),
                       rep = rep(1:2, 6)),
            data.frame(scen = c("inter_C0.8_n200", "quad_C0.8_n200"), rep = 3L))
if (STAGE == "B") DS <- DS[(seq_len(nrow(DS)) - 1L) %% NPART + 1L == PART, ]
NS <- if (STAGE == "A") 10L else 100L
NM <- if (STAGE == "A") 5L else 100L

for (i in seq_len(nrow(DS))) {
  f <- file.path(VD, sprintf("%s_%s_r%04d.csv", STAGE, DS$scen[i], DS$rep[i]))
  if (file.exists(f)) next
  sc <- SC[SC$scen == DS$scen[i], ]; r <- DS$rep[i]
  s  <- SEEDB + sc$id * 100000L + r
  set.seed(s); dat <- gen(sc)
  dat <- as.data.frame(lapply(dat, as.vector))
  fo  <- frm(dat); environment(fo) <- globalenv()

  set.seed(s + 500000000L)
  t0 <- proc.time()[["elapsed"]]
  invisible(utils::capture.output(a <- suppressMessages(suppressWarnings(
    BAGofT::BAGofT(testModel = BAGofT::testGlmBi(formula = fo, link = "logit"),
                   parFun = BAGofT::parRF(ntree = 60), data = dat, nsplits = NS,
                   ne = floor(5 * sqrt(nrow(dat))), nsim = NM)))))
  ta <- proc.time()[["elapsed"]] - t0

  set.seed(s + 500000000L)
  t0 <- proc.time()[["elapsed"]]
  b  <- suppressWarnings(bagoft_fast_pre(dat, fo, nsplits = NS, nsim = NM, ntree = 60L))
  tb <- proc.time()[["elapsed"]] - t0

  k <- c("p.value", "p.value2", "p.value3", "pmean", "pmedian", "pmin")
  idk <- vapply(k, function(x) identical(unname(a[[x]]), unname(b[[x]])), TRUE)
  ids <- identical(unname(a$simRes$pmeanSim), unname(b$simRes$pmeanSim)) &&
         identical(unname(a$simRes$pmediansim), unname(b$simRes$pmediansim)) &&
         identical(unname(a$simRes$pminsim), unname(b$simRes$pminsim))
  row <- data.frame(stage = STAGE, scen = sc$scen, fam = sc$fam, C = sc$C, n = sc$n, rep = r, dseed = s,
                    nsplits = NS, nsim = NM,
                    p_pkg = a$p.value, p_fast = b$p.value, p2_pkg = a$p.value2, p2_fast = b$p.value2,
                    p3_pkg = a$p.value3, p3_fast = b$p.value3,
                    pmean_pkg = a$pmean, pmean_fast = b$pmean, pmin_stat_pkg = a$pmin, pmin_stat_fast = b$pmin,
                    max_abs_sim_diff = max(abs(c(a$simRes$pmeanSim - b$simRes$pmeanSim,
                                                 a$simRes$pmediansim - b$simRes$pmediansim,
                                                 a$simRes$pminsim - b$simRes$pminsim))),
                    p_identical = idk[["p.value"]], p3_identical = idk[["p.value3"]],
                    stats_identical = all(idk[4:6]), sims_identical = ids, all_identical = all(idk) && ids,
                    t_pkg = ta, t_fast = tb)
  tmp <- paste0(f, ".part"); utils::write.csv(row, tmp, row.names = FALSE); file.rename(tmp, f)
  cat(sprintf("%s %s %s r%d  p %.2f/%.2f  p3 %.2f/%.2f  pmean %.12f/%.12f  %s  (%.0f s / %.0f s)\n",
              format(Sys.time(), "%H:%M"), STAGE, sc$scen, r, a$p.value, b$p.value, a$p.value3, b$p.value3,
              a$pmean, b$pmean, if (row$all_identical) "IDENTICAL" else "*** DIFFERS ***", ta, tb))
  flush.console()
}
cat("done", STAGE, PART, "\n")
